25	 * are kept as-is; without one, the default country code {@code +61} is assumed and a
26	 * single leading {@code 0} is dropped from the national digits. The result must carry
27	 * between 8 and 15 digits after the {@code +}. This E.164 string is what gets stored,
28	 * returned, and compared when detecting duplicate telephones.
29	 */
30	@Component
31	public class TelephoneNormalizer {
32	
33	    private static final String DEFAULT_COUNTRY_CODE = "61";
34	
35	    private static final int MIN_DIGITS = 8;
36	
37	    private static final int MAX_DIGITS = 15;
38	
39	    /**
40	     * Converts {@code raw} into its E.164 representation.
41	     *
42	     * @param raw the submitted telephone value
43	     * @return the normalized E.164 telephone number (a leading {@code +} followed by digits)
44	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
45	     */
46	    public String normalize(String raw) {
47	        String trimmed = raw == null ? "" : raw.strip();
48	        boolean explicitCountryCode = trimmed.startsWith("+");
49	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
50	
51	        String digits;
52	        if (explicitCountryCode) {
53	            digits = stripped.substring(1);
54	        } else {
55	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
56	            digits = DEFAULT_COUNTRY_CODE + national;
57	        }
58	
59	        if (!digits.matches("\\d{" + MIN_DIGITS + "," + MAX_DIGITS + "}")) {
60	            throw new InvalidTelephoneException(raw);
61	        }
62	        return "+" + digits;
63	    }
